function (doc) {
  if (doc.type !== "content") return;
  if (doc.status !== "published") return;
  if (typeof doc.publishDate !== "number") return;
  var tags = doc.parentTags;
  if (!tags || !tags.length) return;
  for (var i = 0; i < tags.length; i++) {
    if (tags[i]) emit([tags[i], doc.publishDate], null);
  }
}
